struct modinfo{ui mod, root;};
template<modinfo const&ref>
struct modular{
	static constexpr ui const& MOD = ref.mod;
	static modular root(){ return modular(ref.root); }
	ui val;
	modular(i64 v = 0){ s(v % MOD + MOD); }
	modular& s(ui v){
		val = v < MOD ? v : v - MOD;
		return *this;
	}
	modular operator-() const{ return modular() - *this; }
	modular& operator+=(const modular& rhs){ return s(val + rhs.val); }
	modular& operator-=(const modular& rhs){ return s(val + MOD - rhs.val); }
	modular& operator*=(const modular& rhs){
		val = (ull)val * rhs.val % MOD;
		return *this;
	}
	modular& operator/=(const modular& rhs){ return *this *= rhs.inv(); }
	modular operator+(const modular& rhs) const{ return modular(*this) += rhs; }
	modular operator-(const modular& rhs) const{ return modular(*this) -= rhs; }
	modular operator*(const modular& rhs) const{ return modular(*this) *= rhs; }
	modular operator/(const modular& rhs) const{ return modular(*this) /= rhs; }
	modular pow(int e) const{
		modular res(1), base(*this);
		while(e){
			if(e & 1) res *= base;
			base *= base;
			e >>= 1;
		}
		return res;
	}
	modular inv() const{ return pow(MOD - 2); }
	friend modular operator+(int x, const modular& y){ return modular(x) + y; }
	friend modular operator-(int x, const modular& y){ return modular(x) - y; }
	friend modular operator*(int x, const modular& y){ return modular(x) * y; }
	friend modular operator/(int x, const modular& y){ return modular(x) / y; }
	friend ostream& operator<<(ostream& os, const modular& m){ return os << m.val; }
	friend istream& operator>>(istream& is, modular& m){ i64 x; is >> x; m = modular(x); return is; }
	bool operator<(const modular& r) const{ return val < r.val; }
	bool operator==(const modular& r) const{ return val == r.val; }
	bool operator!=(const modular& r) const{ return val != r.val; }
	explicit operator bool() const{ return val; }
};

modinfo base_info{998244353, 3};
using mint = modular<base_info>;

const int MAX_N = 10010;
mint factorial[MAX_N], inv_factorial[MAX_N], inv[MAX_N];
void precompute_factorials(){
	factorial[0] = 1;
	loop(i, 1, MAX_N){
		factorial[i] = factorial[i - 1] * i;
	}
	inv_factorial[MAX_N - 1] = factorial[MAX_N - 1].inv();
	for(int i = MAX_N - 2; i >= 0; --i){
		inv_factorial[i] = inv_factorial[i + 1] * (i + 1);
	}
	for(int i = MAX_N - 1; i >= 1; --i){
		inv[i] = inv_factorial[i] * factorial[i - 1];
	}
}
mint nCr(int n, int r){
	return factorial[n] * inv_factorial[n - r] * inv_factorial[r];
}
mint binomial(int a, int b){
	return factorial[a + b] * inv_factorial[a] * inv_factorial[b];
}
mint catalan_number(int n){
	return binomial(n, n) - (n - 1 >= 0 ? binomial(n - 1, n + 1) : 0);
}

void solve(){
	int n, m; cin >> n >> m >> base_info.mod;
	precompute_factorials();

	mint result;
	loop(length, 1, m){
		mint term1 = mint(length + 1).pow(length) * length / (n - length) * inv_factorial[length];
		rep(i, m - length){
			int j = i + length;
			mint term2 = mint(n - length).pow(i) * inv_factorial[i];
			mint term3 = (n - j) * mint(n + 1).pow(m - 1 - j) * factorial[j];
			result += term1 * term2 * term3;
		}
	}
	result *= mint(2).pow(m - 1) * (n + 1 - m);
	out(result);
}

